        sameDayFleet: 'We have no repair times from this garage — across the fleet the car usually comes back the same day.',
        timeUnknown: 'We don\'t know how long this garage takes for this repair.',

        // Whether the repair sticks. Bounded by the 90-day window the measurement actually uses — the
        // data cannot say "comes back after 40 days", only whether it came back within three months.
        //
        // THE PERCENTAGE LEADS. "6 in 10" and "8 in 10" are two roundings of one measurement and the eye
